Here is the wrapper:

```ts
export async function withFallback<T>(fns: Array<() => Promise<T>>): Promise<T> {
  let last: unknown;
  for (const fn of fns) {
    try {
      return await fn();
    } catch (err) {
      last = err;
    }
  }
  throw last;
}
```

It tries each function in order and rethrows the final error if all of them fail.
